parameters.jsCode:
const edges = $input.first().json.data?.posts?.edges || [];

const blocks = [
  {
    type: "header",
    text: {
      type: "plain_text",
      text: "Buffer Draft Posts This Week"
    }
  },
  {
    type: "section",
    text: {
      type: "mrkdwn",
      text: "Here are the current draft posts from Buffer."
    }
  },
  {
    type: "divider"
  }
];

for (const [index, edge] of edges.entries()) {
  const post = edge.node || {};

  const channelName =
    post.channel?.displayName ||
    post.channel?.name ||
    post.channelId ||
    "Unknown channel";

  const platform =
    post.channel?.service ||
    "Unknown platform";

  const text =
    post.text?.trim() ||
    "(no text)";

  // ✅ Added publish date
  const dueDate = post.dueAt
    ? new Date(post.dueAt).toLocaleString("en-SG", {
        timeZone: "Asia/Singapore"
      })
    : "Not scheduled";

  const imageUrl = post.assets?.[0]?.thumbnail;

  blocks.push({
    type: "section",
    text: {
      type: "mrkdwn",
      text: `*Channel:* ${channelName}\n*Platform:* ${platform}\n*Publish:* ${dueDate}\n*Text:* ${text}`
    }
  });

  if (imageUrl) {
    blocks.push({
      type: "image",
      image_url: imageUrl,
      alt_text: post.assets?.[0]?.image?.altText || "draft image"
    });
  }

  if (index < edges.length - 1) {
    blocks.push({ type: "divider" });
  }
}

return [
  {
    json: {
      text: `Buffer Draft Posts This Week (${edges.length})`,
      blocks
    }
  }
];
